func:
// Katalog: DAS hier passt du an dein Haus an. Alles andere bleibt.
const nr = env.get("NODERED_URL") || "http://127.0.0.1:1880";
const cmd = (id) => ({ url: nr + "/pi-control/cmd?id=" + id, method: "POST" });

const endpoints = [
  // ---- Pumpe -------------------------------------------------------------
  { id: "pump", label: "Pumpe", kind: "switch", group: "Pumpe",
    invoke: { mqttTopic: env.get("MQTT_COMMAND_TOPIC"), mqttPayloadOn: "ON", mqttPayloadOff: "OFF" } },
  { id: "pump_watts", label: "Pumpenleistung", kind: "read", unit: "W", group: "Pumpe" },
  { id: "pump_minutes_today", label: "Laufzeit heute", kind: "read", unit: "min", group: "Pumpe" },
  { id: "bewaesserung", label: "Bewässerung starten", kind: "number", unit: "min", min: 1, max: 120,
    group: "Pumpe", description: "Startet die Pumpe für die angegebene Zeit.", invoke: cmd("bewaesserung") },
  { id: "nachtruhe", label: "Nachtruhe", kind: "switch", group: "Pumpe",
    description: "Blockt Bewässerung abends und nachts.", invoke: cmd("nachtruhe") },

  // ---- Energie -----------------------------------------------------------
  { id: "pv_surplus_w", label: "PV-Überschuss", kind: "read", unit: "W", group: "Energie" },
  { id: "price_ct", label: "Strompreis", kind: "read", unit: "ct/kWh", group: "Energie" },
  { id: "only_surplus", label: "Nur bei Überschuss pumpen", kind: "switch", group: "Energie",
    invoke: cmd("only_surplus") },
  { id: "surplus_threshold_w", label: "Überschuss-Schwelle", kind: "number", unit: "W",
    min: 0, max: 3000, group: "Energie", invoke: cmd("surplus_threshold_w") },

  // ---- Wetter ------------------------------------------------------------
  { id: "outside_temp_c", label: "Außentemperatur", kind: "read", unit: "°C", group: "Wetter" },
  { id: "rain_24h_mm", label: "Regen nächste 24 h", kind: "read", unit: "mm", group: "Wetter" },
  { id: "rain_block_mm", label: "Regen-Sperre", kind: "number", unit: "mm", min: 0, max: 20,
    group: "Wetter", invoke: cmd("rain_block_mm") },

  // ---- Strategie ---------------------------------------------------------
  { id: "strategy", label: "Strategie", kind: "action", group: "Strategie",
    options: ["automatik", "ueberschuss", "immer", "aus"], invoke: cmd("strategy") },
  { id: "strategy_applied", label: "Zuletzt angewandt", kind: "read", group: "Strategie" },
  { id: "strategy_reason", label: "Begründung", kind: "read", group: "Strategie" }
];

// Startwerte für die einstellbaren Endpunkte (nur beim ersten Lauf)
if (flow.get("strategy") === undefined) {
  flow.set("strategy", "automatik");
  flow.set("only_surplus", true);
  flow.set("nachtruhe", false);
  flow.set("surplus_threshold_w", Number(env.get("SURPLUS_THRESHOLD_W")) || 800);
  flow.set("rain_block_mm", Number(env.get("RAIN_BLOCK_MM")) || 3);
}

msg.url = env.get("LOCAL_ANNOUNCE_URL");
msg.headers = { "content-type": "application/json",
  authorization: "Bearer " + (env.get("PI_INGEST_TOKEN") || "") };
msg.payload = {
  source: "node-red",
  endpoints: endpoints,
  values: {
    strategy: flow.get("strategy"),
    only_surplus: flow.get("only_surplus"),
    nachtruhe: flow.get("nachtruhe"),
    surplus_threshold_w: flow.get("surplus_threshold_w"),
    rain_block_mm: flow.get("rain_block_mm")
  }
};
return msg;

// MQTT → Endpunktwerte. Anpassen: nur die Themen oben im Tab-Env.
const t = msg.topic || "";
const raw = msg.payload;
const num = (v) => { const n = Number(v); return Number.isFinite(n) ? n : null; };
const out = {};

const T = {
  pump: env.get("MQTT_PUMP_STATE_TOPIC"),
  power: env.get("MQTT_POWER_TOPIC"),
  pv: env.get("MQTT_PV_TOPIC"),
  temp: env.get("MQTT_TEMP_TOPIC"),
  rain: env.get("MQTT_RAIN_TOPIC"),
  price: env.get("MQTT_PRICE_TOPIC")
};

if (t === T.pump) {
  const on = String(raw).toUpperCase() === "ON" || raw === true || raw === 1;
  const was = flow.get("pump_on");
  if (was !== on) {
    // Laufzeit heute mitzählen
    const today = new Date().toISOString().slice(0, 10);
    if (flow.get("runtime_day") !== today) { flow.set("runtime_day", today); flow.set("runtime_min", 0); }
    if (on) { flow.set("pump_since", Date.now()); }
    else {
      const since = flow.get("pump_since");
      if (since) {
        const mins = (Date.now() - since) / 60000;
        flow.set("runtime_min", Math.round(((flow.get("runtime_min") || 0) + mins) * 10) / 10);
        flow.set("pump_since", null);
      }
    }
    out.pump_minutes_today = flow.get("runtime_min") || 0;
  }
  flow.set("pump_on", on);
  out.pump = on;
} else if (t === T.power) {
  let w = null;
  if (raw && typeof raw === "object") {
    w = num(raw.ENERGY && raw.ENERGY.Power) ?? num(raw.Power) ?? num(raw.watts);
  } else { w = num(raw); }
  if (w !== null) { out.pump_watts = w; flow.set("watts", w); }
} else if (t === T.pv) {
  const w = num(typeof raw === "object" ? raw.value : raw);
  if (w !== null) { out.pv_surplus_w = w; flow.set("pv", w); }
} else if (t === T.temp) {
  const c = num(typeof raw === "object" ? raw.value : raw);
  if (c !== null) { out.outside_temp_c = c; flow.set("temp", c); }
} else if (t === T.rain) {
  const mm = num(typeof raw === "object" ? raw.value : raw);
  if (mm !== null) { out.rain_24h_mm = mm; flow.set("rain", mm); }
} else if (t === T.price) {
  const ct = num(typeof raw === "object" ? raw.value : raw);
  if (ct !== null) { out.price_ct = ct; flow.set("price", ct); }
} else {
  return null; // unbekanntes Thema: ignorieren
}

// 5 Sekunden Entprellung pro Wert
const send = {};
const now = Date.now();
for (const k of Object.keys(out)) {
  const key = "last_" + k;
  const last = flow.get(key) || { at: 0, v: undefined };
  if (last.v === out[k] && now - last.at < 5000) continue;
  flow.set(key, { at: now, v: out[k] });
  send[k] = out[k];
}
if (!Object.keys(send).length) return null;

msg.url = env.get("LOCAL_ANNOUNCE_URL");
msg.headers = { "content-type": "application/json",
  authorization: "Bearer " + (env.get("PI_INGEST_TOKEN") || "") };
msg.payload = { source: "node-red", values: send };
return msg;

// Kommandos von Pi Control (Steuerung, Alexa, Telegram, Chat, Debug-Testschuss)
const q = msg.req && msg.req.query ? msg.req.query : {};
const body = (msg.payload && typeof msg.payload === "object") ? msg.payload : {};
const id = String(body.id || q.id || "").toLowerCase();
let value = body.value !== undefined ? body.value : q.value;
if (value === "true") value = true;
if (value === "false") value = false;
if (typeof value === "string" && value !== "" && !isNaN(Number(value))) value = Number(value);

const topic = env.get("MQTT_COMMAND_TOPIC");
const report = {};
let mqtt = null;
let ok = true;
let note = "";

const publish = (on) => ({ topic: topic, payload: on ? "ON" : "OFF", qos: 0, retain: false });

switch (id) {
  case "pump":
    mqtt = publish(value === true || value === "ON" || Number(value) > 0);
    report.pump = value === true || value === "ON" || Number(value) > 0;
    break;
  case "bewaesserung": {
    const min = Math.max(1, Math.min(120, Number(value) || 10));
    if (flow.get("nachtruhe") === true) { ok = false; note = "Nachtruhe aktiv"; break; }
    if ((flow.get("rain") || 0) >= (flow.get("rain_block_mm") || 3)) { ok = false; note = "Regen erwartet"; break; }
    flow.set("irrigate_until", Date.now() + min * 60000);
    mqtt = publish(true);
    report.pump = true;
    report.strategy_applied = "manuell";
    report.strategy_reason = "Bewässerung " + min + " Minuten";
    note = min + " Minuten";
    break;
  }
  case "nachtruhe":
    flow.set("nachtruhe", value === true);
    report.nachtruhe = value === true;
    if (value === true && flow.get("pump_on")) { mqtt = publish(false); report.pump = false; }
    break;
  case "only_surplus":
    flow.set("only_surplus", value === true);
    report.only_surplus = value === true;
    break;
  case "surplus_threshold_w":
    flow.set("surplus_threshold_w", Math.max(0, Math.min(3000, Number(value) || 0)));
    report.surplus_threshold_w = flow.get("surplus_threshold_w");
    break;
  case "rain_block_mm":
    flow.set("rain_block_mm", Math.max(0, Math.min(20, Number(value) || 0)));
    report.rain_block_mm = flow.get("rain_block_mm");
    break;
  case "strategy": {
    const allowed = ["automatik", "ueberschuss", "immer", "aus"];
    const v = String(value || "").toLowerCase();
    if (allowed.indexOf(v) === -1) { ok = false; note = "unbekannte Strategie"; break; }
    flow.set("strategy", v);
    report.strategy = v;
    if (v === "aus" && flow.get("pump_on")) { mqtt = publish(false); report.pump = false; }
    break;
  }
  default:
    ok = false;
    note = "unbekannter Endpunkt " + id;
}

const res = { payload: { ok: ok, id: id, value: value, note: note } };
const values = Object.keys(report).length
  ? { url: env.get("LOCAL_ANNOUNCE_URL"),
      headers: { "content-type": "application/json",
                 authorization: "Bearer " + (env.get("PI_INGEST_TOKEN") || "") },
      payload: { source: "node-red", values: report } }
  : null;
const resMsg = Object.assign({}, msg, res);
resMsg.statusCode = ok ? 200 : 400;
return [mqtt, values, resMsg];

// Regel-Baustein: alle 5 Minuten entscheiden, ob gepumpt wird.
const strategy = flow.get("strategy") || "automatik";
const night = flow.get("nachtruhe") === true;
const pv = Number(flow.get("pv") || 0);
const rain = Number(flow.get("rain") || 0);
const price = flow.get("price");
const thr = Number(flow.get("surplus_threshold_w") || 800);
const rainBlock = Number(flow.get("rain_block_mm") || 3);
const on = flow.get("pump_on") === true;
const until = flow.get("irrigate_until") || 0;
const hour = new Date().getHours();
const from = Number(env.get("NIGHT_FROM_HOUR")) || 21;
const to = Number(env.get("NIGHT_TO_HOUR")) || 7;
const quietHour = from > to ? (hour >= from || hour < to) : (hour >= from && hour < to);

let want = on;
let reason = "";

if (until && Date.now() < until) {
  want = true; reason = "manuelle Bewässerung läuft";
} else {
  if (until) flow.set("irrigate_until", 0);
  if (strategy === "aus") { want = false; reason = "Strategie aus"; }
  else if (night && quietHour) { want = false; reason = "Nachtruhe"; }
  else if (rain >= rainBlock) { want = false; reason = "Regen " + rain + " mm erwartet"; }
  else if (strategy === "immer") { want = true; reason = "Strategie immer"; }
  else if (strategy === "ueberschuss" || flow.get("only_surplus") === true) {
    want = pv >= thr;
    reason = want ? "PV-Überschuss " + pv + " W" : "zu wenig Überschuss (" + pv + " von " + thr + " W)";
  } else {
    want = pv >= thr || (typeof price === "number" && price <= 10);
    reason = want ? "Automatik: günstig oder Überschuss" : "Automatik: warten";
  }
}

const values = { url: env.get("LOCAL_ANNOUNCE_URL"),
  headers: { "content-type": "application/json",
             authorization: "Bearer " + (env.get("PI_INGEST_TOKEN") || "") },
  payload: { source: "node-red", values: { strategy_applied: strategy, strategy_reason: reason } } };

let mqtt = null;
if (want !== on) {
  mqtt = { topic: env.get("MQTT_COMMAND_TOPIC"), payload: want ? "ON" : "OFF", qos: 0, retain: false };
  values.payload.values.pump = want;
}
return [mqtt, values];

msg.url = env.get("LOCAL_TRACE_URL");
msg.headers = { "content-type": "application/json",
  authorization: "Bearer " + (env.get("PI_INGEST_TOKEN") || "") };
msg.payload = { component: "node-red", status: "error",
  message: String((msg.error && msg.error.message) || "Fehler"),
  metrics: { source: (msg.error && msg.error.source && msg.error.source.id) || null } };
return msg;
